#include <iostream>
#include <vector>
#include <queue>
#include <tuple>

using namespace std;

const long long INF = 1e18;

struct Edge {
    int to;
    int time;
    int cost;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int V, N, M;
    if (!(cin >> V >> N >> M)) return 0;

    vector<vector<Edge>> adj(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v, t, p;
        cin >> u >> v >> t >> p;
        adj[u].push_back({v, t, p});
        adj[v].push_back({u, t, p});
    }

    int X, Y;
    cin >> X >> Y;

    // dist[u][c] = menor tempo para chegar no vértice u gastando c de custo
    vector<vector<long long>> dist(N + 1, vector<long long>(V + 1, INF));

    // priority_queue armazena tuplas: (tempo, vertice, custo)
    using State = tuple<long long, int, int>;
    priority_queue<State, vector<State>, greater<State>> pq;

    dist[X][0] = 0;
    pq.push({0, X, 0});

    while (!pq.empty()) {
        auto [d, u, c] = pq.top();
        pq.pop();

        if (d > dist[u][c]) continue;

        for (const auto& edge : adj[u]) {
            int nxt_c = c + edge.cost;
            if (nxt_c <= V) {
                long long nxt_d = d + edge.time;
                if (nxt_d < dist[edge.to][nxt_c]) {
                    dist[edge.to][nxt_c] = nxt_d;
                    pq.push({nxt_d, edge.to, nxt_c});
                }
            }
        }
    }

    long long ans = INF;
    for (int c = 0; c <= V; ++c) {
        if (dist[Y][c] < ans) {
            ans = dist[Y][c];
        }
    }

    if (ans == INF) {
        cout << -1 << "\n";
    } else {
        cout << ans << "\n";
    }

    return 0;
}
